import json
from bs4 import BeautifulSoup

html = """<html><head>
<meta property="og:title" content="Steel Kettle">
<script type="application/ld+json">
{"@type": "Product", "name": "Steel Kettle", "offers": {"price": "29.90", "priceCurrency": "EUR"}}
</script></head><body><h1 class="pdp-title-x7">Steel Kettle</h1></body></html>"""
soup = BeautifulSoup(html, "html.parser")

def product_from_jsonld(soup):
    for s in soup.find_all("script", type="application/ld+json"):
        data = json.loads(s.string or "{}")
        if data.get("@type") == "Product":
            return {"name": data["name"], "price": float(data["offers"]["price"])}
    return None

def og(soup, prop):
    tag = soup.find("meta", property=f"og:{prop}")
    return tag["content"] if tag else None

print(product_from_jsonld(soup))   # {'name': 'Steel Kettle', 'price': 29.9}
print(og(soup, "title"), og(soup, "image"))   # Steel Kettle None
